import numpy as np
import os, sys
sys.path.append('storage/verity')
try:
    import sqp_core_v1 as sqp1
except Exception as e:
    sqp1 = None

N = 32

def _seed_grid_minus_corners():
    xs = np.linspace(0.1, 0.9, 6)
    ys = np.linspace(0.1, 0.9, 6)
    centers = []
    for ix, X in enumerate(xs):
        for iy, Y in enumerate(ys):
            if (ix in (0,5)) and (iy in (0,5)):
                continue
            centers.append([X, Y])
    return np.array(centers, dtype=float)

def _load_baseline():
    C = None
    try:
        C = np.load("storage/verity/best_centers.npy")
        if not (isinstance(C, np.ndarray) and C.shape == (N,2)):
            C = None
    except Exception:
        C = None
    if C is None:
        C = _seed_grid_minus_corners()
    return np.clip(C.astype(float), 0.0, 1.0)

def construct_packing() -> tuple:
    if sqp1 is None:
        C = _seed_grid_minus_corners()
        x, y = C[:,0], C[:,1]
        r = np.maximum(1e-8, np.minimum.reduce([x, 1.0-x, y, 1.0-y]))
        print("[SQP v1] fallback: module import failed; returning safe baseline.")
        return C, r

    C = _load_baseline()
    s0, r0 = sqp1.merit_sum_r(C)
    print(f"[SQP v1] start sum={s0:.15f}")

    best_C, best_r, best_s = C.copy(), r0.copy(), float(s0)
    accepts = 0
    noimp = 0
    max_outer = 24
    basis_idx = list(range(0, N, 2))  # thinned deterministic basis

    for it in range(max_outer):
        improved, C1, R1, S1, info = sqp1.step_sqp_v1(best_C, basis_idx=basis_idx, h=8e-6, tau=0.02)
        print(f"[SQP v1] it={it:02d} s0={info['s0']:.15f} s1={info['s_new']:.15f} "
              f"act_pairs={info['n_act_pair']} A_shape={info['A_shape']} "
              f"h={info['h']:.1e} tau={info['tau']:.3f} basis_len={info['basis_len']}")
        if improved:
            best_C, best_r, best_s = C1, R1, S1
            accepts += 1
            noimp = 0
            # rotate basis to odd indices
            basis_idx = list(range(1, N, 2))
        else:
            noimp += 1
            if noimp >= 6:
                break
            # alternate basis anyway
            basis_idx = list(range((it+1) % 2, N, 2))

        if accepts >= 8:
            break

    if best_s > s0 + 5e-10:
        try:
            os.makedirs("storage/verity", exist_ok=True)
            np.save("storage/verity/best_centers.npy", best_C)
            np.save("storage/verity/best_radii.npy", best_r)
            print(f"[SQP v1] persisted improved packing sum={best_s:.15f}")
        except Exception:
            pass

    return np.array(best_C, dtype=float), np.array(best_r, dtype=float)
